const body = $input.item.json.body || $input.item.json;

const orderId = body.orderId || body.orderNumber || `ORD-${Date.now()}`;
const partnerId = body.partnerId || "PARTNER-DEFAULT";
const partnerName = body.partnerName || "Valued Partner";
let partnerPhone = String(body.partnerPhone || "923270831470").replace(/[^0-9]/g, "");
if (partnerPhone.startsWith("03")) partnerPhone = "92" + partnerPhone.substring(1);

const category = (body.category || "furniture").toLowerCase();
const orderAmount = Number(body.amount || body.orderAmount || 100000);
let commissionRate = Number(body.commissionRate || 0);

// Dynamic Default Commission Rates per Sector Guidelines
if (!commissionRate) {
  if (category.includes("property") || category.includes("real_estate")) {
    commissionRate = 0.015; // 1.5% for high-value real estate
  } else if (category.includes("furniture")) {
    commissionRate = 0.10; // 10% for handcrafted furniture
  } else if (category.includes("event") || category.includes("catering")) {
    commissionRate = 0.05; // 5% for banquet & catering bookings
  } else {
    commissionRate = 0.05;
  }
}

const commissionAmount = Math.round(orderAmount * commissionRate);
const transactionId = `TXN-${new Date().getFullYear()}-${Math.floor(10000 + Math.random() * 90000)}`;
const formattedDate = new Date().toISOString();

return [{
  json: {
    orderId,
    partnerId,
    partnerName,
    partnerPhone,
    category,
    orderAmount,
    commissionRate: (commissionRate * 100).toFixed(1) + "%",
    commissionAmount,
    transactionId,
    formattedDate
  }
}];

